            {
              "id": "WEBD-R2-B-W05-01-A08",
              "text": "The deliberate v0/v1 mismatch is diagnosed from the Application panel and repaired through one shared STORAGE_KEY constant."
            },
            {
              "id": "WEBD-R2-B-W05-01-A09",
              "text": "A human reviewer repeats hard reload, one Done/Remaining comparison, malformed-data preservation, and explicit recovery and records pass or a specific revision."
            }
