            "label": "State and storage responsibility scaffold",
            "content": "\"use strict\";\n\nconst STORAGE_KEY = \"web-foundations.study-checklist.v1\";\nlet storageBlocked = false;\nlet items = loadItems();\nlet currentFilter = \"all\";\n\nfunction freshDefaultItems() {\n  // Return new record objects so DEFAULT_ITEMS remains unchanged.\n}\n\nfunction isValidItems(value) {\n  // Require an array of records with a known string id/title and Boolean done.\n}\n\nfunction loadItems() {\n  // Missing -> defaults. Valid exact shape -> parsed records.\n  // Malformed/invalid -> preserve raw value, set storageBlocked, return display defaults.\n}\n\nfunction saveItems() {\n  // Never write while storageBlocked is true.\n}\n\nfunction deriveVisibleItems() {\n  // Return a filtered view without changing items.\n}\n\nfunction renderChecklist() {\n  // Own the list, progress, empty, warning, filter, and button states.\n}\n\nfunction handleListClick(event) {\n  // Find the nearest generated data-id button, update by stable id, save, render.\n}\n\nfunction handleFilterClick(event) {\n  // Set currentFilter, then render.\n}\n\nfunction handleStorageReset() {\n  // Remove only STORAGE_KEY, restore fresh defaults, unblock, save, render.\n}\n"
