            "content": "\"use strict\";\n\nconst FIXTURES = {\n  normal: \"./data/services.json\",\n  empty: \"./data/empty.json\",\n  missing: \"./data/missing.json\",\n  malformed: \"./data/malformed.json\",\n  invalid: \"./data/invalid-shape.json\"\n};\n\nlet currentServices = [];\nlet hasValidResult = false;\nlet lastRequestedUrl = FIXTURES.normal;\n\nfunction isValidService(value) {\n  // Require non-empty string id, name, category, and description.\n}\n\nfunction isValidServiceList(value) {\n  // Require an array whose every record is valid.\n}\n\nfunction renderServices(services) {\n  // Own the cards region and write fixture text through textContent.\n}\n\nasync function loadServices(url) {\n  lastRequestedUrl = url;\n  // Loading -> fetch -> ok check -> one parse -> shape check -> commit/render.\n  // On failure preserve currentServices, render error, log technical evidence.\n}\n\nfunction handleFixtureClick(event) {\n  // Read the supplied fixture key and call loadServices.\n}\n\nfunction handleRetry() {\n  // Request lastRequestedUrl again.\n}\n"
